-- multi tags 系统, 配合 c#端的 DesiredMultiTags 使用
-- 


local CSGameUtils = CS.GameUtils
local Singleton = import('Frame.Singleton')

---@class DesiredMultiTagsManager
---@field GetInstance fun(self:DesiredMultiTagsManager):DesiredMultiTagsManager
local DesiredMultiTagsManager = Class('DesiredMultiTagsManager', Singleton)



---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Time = CS.UnityEngine.Time
local Mathf = CS.UnityEngine.Mathf
local AnimationCurve = CS.UnityEngine.AnimationCurve
local Physics = CS.UnityEngine.Physics
local Quaternion = CS.UnityEngine.Quaternion
local RaycastHit = CS.UnityEngine.RaycastHit
local QueryTriggerInteraction = CS.UnityEngine.QueryTriggerInteraction
local LayerMask = CS.UnityEngine.LayerMask
local Collider = CS.UnityEngine.Collider
local CapsuleCollider = CS.UnityEngine.CapsuleCollider
local Animator = CS.UnityEngine.Animator


local DesiredMultiTags = CS.Game.DesiredMultiTags



-- ========================================================



-- 两种容器类型:
local List_Int = CS.System.Collections.Generic.List(CS.System.Int32)
local List_String = CS.System.Collections.Generic.List(CS.System.String)
local Dictionary_String_Int = CS.System.Collections.Generic.Dictionary(CS.System.String, CS.System.Int32)
local Dictionary_Int_List = CS.System.Collections.Generic.Dictionary( CS.System.Int32, List_Int )

local HashSet_String = CS.System.Collections.Generic.HashSet(CS.System.String)



-- ========================================================


function DesiredMultiTagsManager:__init()
    --print( "tpr DesiredMultiTagsManager.__init()" )

    -- 通过这两个容器的组合, 来确保:
    -- (1) tag string 是唯一的
    -- (2) 可根据 idx 得到 tag str
    -- (3) 可根据 tag str 得到 tag idx
    self.tagList = List_String() -- 0-based idx, tagIdx->tagStr
    self.tagDict = Dictionary_String_Int() -- Dictionary<tagStr,tagIdx>


    -- 真实存储每个 gameobj-tags 信息的容器:
    self.instanceId_2_tagIdxs = Dictionary_Int_List() -- Dictionary<transform.instanceID, List<int>>


    -- 查重用的容器
    self.tagHashSet = HashSet_String()

    -- ==========================================
    self.WhenAwakeFunc = function( desiredMultiTags_ )
        self:WhenAwake( desiredMultiTags_ )
    end

    self.WhenDestroyFunc = function( desiredMultiTags_ )
        self:WhenDestroy( desiredMultiTags_ )
    end


    if isNull( DesiredMultiTags.WhenAwake ) then
        DesiredMultiTags.WhenAwake = self.WhenAwakeFunc
    end

    if isNull( DesiredMultiTags.WhenDestroy ) then
        DesiredMultiTags.WhenDestroy = self.WhenDestroyFunc
    end
end


function DesiredMultiTagsManager:__delete()
    --print( "tpr DesiredMultiTagsManager.__delete()" )
    -------
    assert( isNotNull( DesiredMultiTags.WhenAwake ) )
    DesiredMultiTags:WhenAwake( "-", self.WhenAwakeFunc )

    assert( isNotNull( DesiredMultiTags.WhenDestroy ) )
    DesiredMultiTags:WhenDestroy( "-", self.WhenDestroyFunc )

    self.WhenAwakeFunc = nil 
    self.WhenDestroyFunc = nil
end





function DesiredMultiTagsManager:WhenAwake( desiredMultiTags_ )

    if desiredMultiTags_.tags.Count == 0 then 
        print( "desiredMultiTags_,tags 为空" )
        return
    end 

    ---
    local instanceId = desiredMultiTags_:GetTheInstanceID()
    if self.instanceId_2_tagIdxs:ContainsKey(instanceId) == true then 
        printError( "异常, 一个 instancID 被多次添加到 容器中, " .. instanceId )
    end

    local tags  = {} -- 去除掉重复元素后的 tags;
    self.tagHashSet:Clear()
    for i=0, desiredMultiTags_.tags.Count-1 do 
        local tag = desiredMultiTags_.tags[i]
        if self.tagHashSet:Contains(tag) == true then
            print( "发现重复 tag: " .. tag .. " in " .. desiredMultiTags_.name )
        else 
            table.insert( tags, tag )
        end 
    end 

    --print( "instanceId = " .. instanceId )
    for i=1, #tags do 
        self:AddInstanceIdTagPair( instanceId, tags[i] )
    end
end



function DesiredMultiTagsManager:WhenDestroy( desiredMultiTags_ )
    if desiredMultiTags_.tags.Count == 0 then 
        print( "desiredMultiTags_,tags 为空 -2-" )
        return
    end 
    self:RemoveInstanceId( desiredMultiTags_:GetTheInstanceID() )
end



-- ===================================================================


-- 外部使用, 检查目标 transform 是否携带指定的 tag_
function DesiredMultiTagsManager:IsContainTag( transformInstanceId_, tagStr_ )

    if self.tagDict:ContainsKey(tagStr_) == false then 
        -- 说明当前整个游戏里都没物体设置了 tagStr_
        return false
    end

    local isGet = nil
    local tagIdx = nil
    local tagIdxList = nil 

    isGet,tagIdx = self.tagDict:TryGetValue( tagStr_ ) -- !!! 必须用此格式来访问 Dictionary 元素
    assert( isGet == true )

    isGet, tagIdxList= self.instanceId_2_tagIdxs:TryGetValue( transformInstanceId_ )
    if isGet == false then 
        -- 说明 目标物体 没有绑定 DesiredMultiTags 脚本组件
        return false
    end 

    for i=0, tagIdxList.Count-1 do 
        if tagIdx == tagIdxList[i] then 
            --print( "koko, IsContainTag() 找到 " .. tagStr_ )
            return true
        end 
    end 

    -- 目标物体 的 DesiredMultiTags 并未携带 tagStr_
    return false
end



-- ===================================================================

-- ret tagIdx
function DesiredMultiTagsManager:RegistTag( tagStr_ )
    local isGet = nil
    local tagIdx = nil
    if self.tagDict:ContainsKey(tagStr_) == true then 
        isGet,tagIdx = self.tagDict:TryGetValue( tagStr_ ) -- !!! 必须用此格式来访问 Dictionary 元素
        assert( isGet == true )
    else
        tagIdx = self.tagList.Count
        self.tagList:Add( tagStr_ )
        self.tagDict:Add( tagStr_, tagIdx )
    end 
    if tagIdx == nil then 
        printError( "未能分配到 tag idx, tag = " .. tagStr_ )
    end
    return tagIdx
end


function DesiredMultiTagsManager:AddInstanceIdTagPair( instanceId_, tagStr_ )

    local tagIdx = self:RegistTag( tagStr_ )
    ------ 
    if self.instanceId_2_tagIdxs:ContainsKey(instanceId_) == false then
        self.instanceId_2_tagIdxs:Add( instanceId_, List_Int() )
    end
    local listContainer = self.instanceId_2_tagIdxs[instanceId_]

    if isNull(listContainer) then
        printError( "异常, instanceId_ = " .. instanceId_ )
    end
    ---
    listContainer:Add( tagIdx )
end



function DesiredMultiTagsManager:RemoveInstanceId( instanceId_ )
    if self.instanceId_2_tagIdxs:ContainsKey(instanceId_) == false  then 
        print( "koko-[Error]:发现 instanceId 不存在: " .. instanceId_ )
        return
    end 

    local isGet, tgtValue= self.instanceId_2_tagIdxs:TryGetValue( instanceId_ )
    assert( isGet == true )
    tgtValue:Clear()

    local isGet = self.instanceId_2_tagIdxs:Remove( instanceId_ )
    assert( isGet == true )
end 


-- 仅用于测试...
function DesiredMultiTagsManager:DebugAll()

    print( "=== tpr DesiredMultiTags 系统: ===========" )
    local ss = ""
    ss = ss .. "\n  tags Num = " .. self.tagList.Count
    ---
    ss = ss .. "\n tagDict: " 
    for k,v in pairs(self.tagDict) do 
        ss = ss .. "\n    " .. k .. "-" .. v .. ";  "
    end 
    print(ss)
    ---
    ss = "\n instanceId_2_tagIdxs: "
    for instanceId,tagIdxs in pairs(self.instanceId_2_tagIdxs) do 

        ss = ss .. "\n     instanceId:" .. instanceId .. " : {"
        for _,tagIdx in pairs(tagIdxs) do 
            if not (tagIdx >= 0 and tagIdx < self.tagList.Count) then
                printError( "有个 tagIdx 没能找到对应的 tag; idx = " .. tagIdx )
                break
            end
            ss = ss .. self.tagList[tagIdx] .. ",  "
        end

        ss = ss .. "}"
    end 
    print(ss)
end


return DesiredMultiTagsManager

